(()=>{'use strict';const form=document.getElementById('fashion-jarvis-form');if(!form)return;const status=document.getElementById('fashion-jarvis-status'),output=document.getElementById('fashion-jarvis-answer'),button=form.querySelector('button[type=submit]'),check=document.getElementById('fashion-jarvis-check');let ready=false,busy=false;
const el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};async function connection(openSetup=false){if(check.disabled)return;check.disabled=true;check.textContent='Checking AI…';status.textContent='Checking your private Jarvis connection…';try{const r=await fetch('/api/jarvis/status',{cache:'no-store',signal:AbortSignal.timeout(12000)});const d=await r.json();if(!r.ok)throw Error('Connection status unavailable. Reload and sign in again.');ready=d.ready===true;status.textContent=ready?'Private key connected. Ask Jarvis to verify model access and account allowance.':!d.owner?'Sign in with the website owner account to connect Jarvis.':'No private key is connected. Enter the full key in Connect your AI, then choose Connect AI securely.';button.disabled=!ready||busy;if(openSetup&&d.owner&&!d.configured){const panel=document.getElementById('jarvis-connect');panel?.scrollIntoView({behavior:'auto',block:'center'});document.getElementById('jarvis-connect-form')?.elements.namedItem('key')?.focus();}}catch(e){ready=false;button.disabled=true;status.textContent=e.name==='TimeoutError'?'Connection check timed out. Check your network and retry.':e.message;}finally{check.disabled=busy;check.textContent='Check AI connection';}}
const specialists=[['morning','Morning fashion report','Research today’s trending fashion brands, rising styles, best-seller evidence and likely drivers. State market, timeframe, dated sources and uncertainty. Separate sales evidence from popularity. Include PR angles, blog ideas, three hooks, a measurement loop and closer draft. End with a short spoken summary.','research'],['blogger','Fashion blogger','Draft a sourced original fashion blog article aligned to my brand. Include headline, angle, factual sources and social excerpts.','research'],['hooks','Content hooks','Prepare ten truthful content hooks for a fashion collection. Ask for confirmed product benefits and plan a small creative test.','plan'],['learning','Learning loop','Help review my campaign metrics. Ask for measurements, propose hypotheses and plan the next test without claiming unproven causation.','plan'],['closer','Customer closer','Help prepare a customer consultation and personalised offer. Ask for requirements, confirmed price, timing and the next approved follow-up.','plan'],['director','Fashion team','Plan my next fashion business milestone. Give specialist briefs, dependencies and the decisions I must approve.','plan'],['research','Research & opportunities','Research suitable public fashion suppliers and business opportunities for my brand. Include proof links, dates, fit criteria and questions to verify.','research'],['pr','PR & fashion influence','Build a factual press-kit outline and research relevant fashion publications or creators. Draft pitches for review and distinguish verified audience evidence from unknowns.','research'],['design','Design assistant','Help me develop an original collection. Ask about customer, occasion, price range, silhouette and fabrics, then propose a concept and sample-development brief.','plan'],['branding','Branding','Help me define my fashion brand positioning, customer hypothesis, story, tone and visual direction using only confirmed facts.','plan'],['marketing','Marketing','Prepare a collection-launch campaign with platform-specific captions, Studio briefs, owner approvals and measurable goals.','plan']];const team=document.getElementById('fashion-jarvis-team');for(const [role,name,prompt,mode]of specialists){const card=el('article');card.className='record';card.append(el('h3',name));const open=el('button','Prepare brief');open.type='button';open.onclick=()=>{const input=form.elements.namedItem('prompt');if(input.value.trim()&&!confirm('Replace your current Jarvis request with this specialist brief?'))return;form.elements.namedItem('role').value=role;form.elements.namedItem('mode').value=mode;input.value=prompt;form.scrollIntoView({behavior:'auto',block:'center'});input.focus();status.textContent='Specialist brief opened. Review the request, then choose Ask Jarvis.';};card.append(open);team.append(card);}check.onclick=()=>{window.dispatchEvent(new Event('jarvis-open-connect'));connection(false);};form.onsubmit=async event=>{event.preventDefault();if(!ready||busy)return;const prompt=form.elements.namedItem('prompt').value.trim();if(!prompt)return;busy=true;button.disabled=true;check.disabled=true;window.speechSynthesis?.cancel();document.getElementById('jarvis-read-report').disabled=true;output.replaceChildren();status.textContent='Jarvis is preparing a draft…';try{let tasks=[];if(form.elements.namedItem('context').checked){let work={};try{work=JSON.parse(localStorage.getItem('zuxuru-designer-work-v1'))||{};}catch{}const map={sales:'sales',marketing:'marketing',branding:'branding',visibility:'visibility_seo',products:'products',opportunities:'opportunities',skills:'ai_skills',career:'career'};tasks=(work.tasks||[]).filter(t=>!t.done).slice(0,12).map(t=>({module:map[t.area]||'opportunities',title:t.title,deliverable:t.deliverable,done:false}));}const r=await fetch('/api/jarvis/chat',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({prompt,role:form.elements.namedItem('role').value,mode:form.elements.namedItem('mode').value,tasks}),signal:AbortSignal.timeout(65000)});const d=await r.json();if(!r.ok)throw Error(d.error||'Jarvis request failed');output.append(el('p',d.answer));window.bongaJarvisVoiceText=String(d.answer||'');document.getElementById('jarvis-read-report').disabled=!window.speechSynthesis;for(const source of d.sources||[]){try{const u=new URL(source.url);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)continue;const a=el('a',source.title||u.hostname);a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';const p=el('p');p.append(a);output.append(p);}catch{}}const map={visibility_seo:'visibility',ai_skills:'skills',career:'career'};for(const t of d.tasks||[]){const card=el('article');card.className='record';card.append(el('h3',t.title),el('p',t.deliverable));const review=el('button','Review task');review.type='button';review.onclick=()=>{const f=document.getElementById('designer-task-form');if(['title','deliverable','due'].some(k=>f.elements.namedItem(k).value)&&!confirm('Replace the unsaved task brief?'))return;delete f.dataset.sourceOrderId;f.elements.namedItem('area').value=map[t.module]||t.module;f.elements.namedItem('title').value=String(t.title).slice(0,200);f.elements.namedItem('deliverable').value=String(t.deliverable||'').slice(0,1000);f.elements.namedItem('due').value='';location.hash='my-work';f.scrollIntoView({behavior:'auto'});f.elements.namedItem('title').focus();};card.append(review);output.append(card);}status.textContent='AI draft ready for review. No task was saved and no external action was taken.';}catch(e){status.textContent=e.name==='TimeoutError'?'Jarvis timed out. Retry with a shorter request.':e.message;}finally{busy=false;check.disabled=false;button.disabled=!ready;}};document.getElementById('jarvis-read-report').onclick=()=>{if(!window.speechSynthesis)return;window.speechSynthesis.cancel();const voice=new SpeechSynthesisUtterance(String(window.bongaJarvisVoiceText||'').slice(0,16000));voice.lang='en-ZA';voice.onend=()=>document.getElementById('jarvis-voice-status').textContent='Voice readout complete.';voice.onerror=()=>document.getElementById('jarvis-voice-status').textContent='Voice readout unavailable on this device.';window.speechSynthesis.speak(voice);document.getElementById('jarvis-voice-status').textContent='Reading the reviewed AI draft.';};document.getElementById('jarvis-stop-voice').onclick=()=>{window.speechSynthesis?.cancel();document.getElementById('jarvis-voice-status').textContent='Voice stopped.';};window.addEventListener('pagehide',()=>window.speechSynthesis?.cancel());connection();})();
